        if sp and subj(spec.get(sp,{})) != pid: s+=f" !!SPECIMEN-SUBJ={subj(spec.get(sp,{}))}"
        if notes: s+=f" NOTE[{notes}]"
        return s
    if t=='Specimen':
        idw=who(ext(r,'label-mrn'),str(ext(r,'label-dob')))
        s=(f"{T} Spec {i}: acc={r.get('accessionIdentifier',{}).get('value')} coll={r.get('collection',{}).get('collectedDateTime','')[:16]} "
