        return s
    if t=='MedicationAdministration':
        notes=' | '.join(n['text'] for n in r.get('note',[]))
        return f"{T} MedAdmin {i}: {r['medicationCodeableConcept']['text']} {r.get('dosage',{}).get('text')} [{r['status']}] eff={r.get('effectiveDateTime','')[:16]} NOTE[{notes}]"
    if t=='MedicationDispense':
        notes=' | '.join(n['text'] for n in r.get('note',[]))
        return f"{T} MedDisp {i}: {r['medicationCodeableConcept']['text']} qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} handed={r.get('whenHandedOver','')[:16]} instr={[d['text'] for d in r.get('dosageInstruction',[])]} NOTE[{notes}]"
    if t=='DocumentReference':
        return f"{T} Doc {i}: [{r['type']['text']}] author={[a['display'] for a in r.get('author',[])]} role={ext(r,'author-role')}\n     | "+r.get('description','').replace('\n','\n     | ')
    if t=='AllergyIntolerance':
        return f"{T} Allergy {i}: {r['code']['text']} reaction={[m['text'] for rr in r.get('reaction',[]) for m in rr.get('manifestation',[])]}"
    if t=='Task':
        if r['status']=='requested':
            return f"{T} *REQUEST* {i}: {r['code']['coding'][0]['code']} focus={r.get('focus',{}).get('reference')} :: {r.get('description')}"
        return f"{T} ITEM {i}"
    return f"{T} {t} {i}"

def report(pid):
    p=pat[pid]; out=[]
    out.append(f"##### {pid} {p['name'][0]['text']} dob={p['birthDate']} sex={p['gender']} mrn={p['identifier'][0]['value']}")
    for e in eps[pid]:
        out.append(f"  EPISODE {e['id']} start={e['period']['start']} {e['type'][0]['text']}")
    rs=sorted(chart[pid],key=lambda r:(et(r),r['id']))
    accs=[]
    for r in rs:
        out.append("  "+fmt(r,pid))
        a=None
        if r['resourceType']=='Specimen': a=r.get('accessionIdentifier',{}).get('value')
        if r['resourceType']=='Observation': a=(r.get('identifier') or [{}])[0].get('value')
        if a and a not in accs: accs.append(a)
    for a in accs:
        for b in accmap.get(a,[]):
            idw=who(ext(b,'patient-mrn'),str(ext(b,'patient-dob')))
            s=f"  ACC {b['id']}: {a} name={ext(b,'patient-name')}|{ext(b,'patient-mrn')}|{ext(b,'patient-dob')} ->{idw} recv={(ext(b,'received') or '')[:16]} by={b.get('author',{}).get('display')}"
            if not idw.startswith(pid): s+=" !!ACC-MISMATCH"
            out.append(s)
    return '\n'.join(out)
